#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Vellum: everything TestFlight needs that only Zach can do: the bundle ID, the app record in App Store Connect, the
# four repository secrets on millZach/Vellum, and the internal testing group that hands each build to the Duo.
# docs/testflight.md says what each part is for. Run it where gh is signed in to millZach/Vellum (forge):
#   bash apps/ios/Scripts/setup-testflight.sh
# It holds nothing secret. Values pasted here go straight to GitHub secrets; only the non-secret answers are remembered,
# in ~/.config/vellum/testflight.env, outside the repository.
cd "$(dirname "$0")/../../.."
# ssh runs this in a plain shell where mise has not put gh on PATH; without this every secret is skipped.
export PATH="$HOME/.local/share/mise/shims:/usr/bin:$PATH"
command -v gh >/dev/null 2>&1 || { echo "gh not found; install it or run this where it is."; exit 1; }
mkdir -p "$HOME/.config/vellum"
ENV_FILE="$HOME/.config/vellum/testflight.env"
BUNDLE_ID=com.millzach.vellum   # apps/ios/project.yml
# Terminals wrap pastes in escape codes (bracketed paste); strip them and any spaces.
clean() { printf '%s' "$1" | sed $'s/\x1b\\[20[01]~//g' | tr -d '\r\n\t '; }

# ask_clean KEY "Prompt" PATTERN "What it looks like" — ask until the cleaned answer matches PATTERN.
ask_clean() {
  local key="$1" prompt="$2" pattern="$3" hint="$4" value=""
  while :; do
    ask "$key" "$prompt"
    value="$(clean "${!key}")"
    [[ "$value" =~ $pattern ]] && break
    warn "$hint Try again (Ctrl-C to stop)."
  done
  printf -v "$key" '%s' "$value"
}

TOTAL_STAGES=7
banner "Vellum TestFlight setup"

stage "Check GitHub access"
say "The secrets go on millZach/Vellum through gh."
if gh auth status >/dev/null 2>&1 && [[ "$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null)" == "millZach/Vellum" ]]; then
  say "${GREEN}✓${RESET} gh is signed in and points at millZach/Vellum."
else
  warn "gh is not signed in, or this folder is not millZach/Vellum. Secrets will be listed at the end to set by hand."
fi
pause

stage "Register the bundle ID"
open_url "https://developer.apple.com/account/resources/identifiers/list"
say "If $BUNDLE_ID is already in the list, skip this stage."
step "Press +, choose App IDs, then Continue. Choose App, then Continue."
step "Description: Vellum. Bundle ID: Explicit, $BUNDLE_ID."
step "Leave the capabilities as they are. Continue, then Register."
note "Apple may say the ID is taken by another team; then project.yml needs a new one, so stop and tell the Vellum thread."
pause

stage "Create the app in App Store Connect"
open_url "https://appstoreconnect.apple.com/apps"
say "If an app with bundle ID $BUNDLE_ID is already there, skip this stage."
step "Press the + next to Apps, then New App."
step "Platform: iOS. Name: Vellum. If the name is taken, use Vellum Canvas; only you see it in TestFlight."
step "Primary language: English (U.S.). Bundle ID: pick $BUNDLE_ID. SKU: vellum. User access: Full Access."
step "Create."
ask APP_NAME "App name you used:"
APP_NAME="$(printf '%s' "${APP_NAME:-}" | sed $'s/\x1b\\[20[01]~//g' | tr -d '\r\n')"
write_env APP_NAME "${APP_NAME:-Vellum}"
pause

stage "Team ID"
open_url "https://developer.apple.com/account#MembershipDetailsCard"
step "Under Membership details, copy the Team ID (10 letters and digits)."
ask_clean APPLE_TEAM_ID "Paste the Team ID:" '^[A-Z0-9]{10}$' "A Team ID is 10 capital letters and digits."
set_secret APPLE_TEAM_ID "$APPLE_TEAM_ID"
pause

stage "App Store Connect API key (Admin)"
open_url "https://appstoreconnect.apple.com/access/integrations/api"
say "The key must have the ${BOLD}Admin${RESET} role: cloud-managed signing, which the workflow uses, refuses App Manager keys."
say "If you already have an Admin Team Key and its .p8, reuse it. Otherwise:"
step "Team Keys → Generate API Key (or +). Name: Vellum CI Admin. Access: Admin. Generate."
step "Download the .p8 (Apple lets you download it once)."
step "Copy the Issuer ID shown above the keys table, and the key's Key ID from its row."
ask_clean APP_STORE_CONNECT_ISSUER_ID "Paste the Issuer ID:" \
  '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' "An Issuer ID looks like 1a2b3c4d-…, 36 characters."
ask_clean APP_STORE_CONNECT_KEY_ID "Paste the Key ID:" '^[A-Za-z0-9]{10}$' "A Key ID is 10 letters and digits."
APP_STORE_CONNECT_KEY_ID="$(printf '%s' "$APP_STORE_CONNECT_KEY_ID" | tr '[:lower:]' '[:upper:]')"
write_env APP_STORE_CONNECT_ISSUER_ID "$APP_STORE_CONNECT_ISSUER_ID"
write_env APP_STORE_CONNECT_KEY_ID "$APP_STORE_CONNECT_KEY_ID"
set_secret APP_STORE_CONNECT_ISSUER_ID "$APP_STORE_CONNECT_ISSUER_ID"
set_secret APP_STORE_CONNECT_KEY_ID "$APP_STORE_CONNECT_KEY_ID"
pause

stage "Paste the key"
say "Open AuthKey_${APP_STORE_CONNECT_KEY_ID}.p8 on the laptop in Notepad, select all, copy, and paste it here."
say "It starts with -----BEGIN PRIVATE KEY----- and ends with -----END PRIVATE KEY-----."
note "Or, if you copied the file to this machine, type its path instead of pasting."
P8_TEXT=""
while :; do
  printf '  %sPaste the key (or a path), then Enter:%s\n' "$BOLD" "$RESET"
  P8_TEXT=""
  while IFS= read -r line; do
    line="$(printf '%s' "$line" | sed $'s/\x1b\\[20[01]~//g' | tr -d '\r')"
    if [[ -z "$P8_TEXT" && "$line" != *BEGIN* ]]; then   # a path, not a pasted key
      p="$(clean "$line")"; p="${p:-$HOME/AuthKey_${APP_STORE_CONNECT_KEY_ID}.p8}"; p="${p/#\~/$HOME}"
      [[ -f "$p" ]] && P8_TEXT="$(sed $'s/\x1b\\[20[01]~//g' "$p" | tr -d '\r')"
      break
    fi
    P8_TEXT+="$line"$'\n'
    [[ "$line" == *"END PRIVATE KEY"* ]] && break
  done
  if [[ "$P8_TEXT" == *"BEGIN PRIVATE KEY"* && "$P8_TEXT" == *"END PRIVATE KEY"* ]]; then break; fi
  warn "That wasn't a whole key (or no file there). Try again: paste everything from BEGIN to END."
done
P8_TEXT="$(printf '%s' "$P8_TEXT" | sed -n '/BEGIN PRIVATE KEY/,/END PRIVATE KEY/p' | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')"
set_secret APP_STORE_CONNECT_KEY "$P8_TEXT"
unset P8_TEXT
if ls "$HOME"/AuthKey_*.p8 >/dev/null 2>&1 && confirm "Delete the AuthKey_*.p8 files in $HOME now that the secret holds the key?"; then
  rm -f "$HOME"/AuthKey_*.p8 && say "${GREEN}✓${RESET} deleted"
fi
say "Keep the laptop copy of the .p8 somewhere safe; Apple won't let you download it again."
pause

stage "TestFlight testers"
say "A processed build reaches the Duo only through a testing group. Once:"
open_url "https://appstoreconnect.apple.com/apps"
step "Open ${APP_NAME:-Vellum} → TestFlight → Internal Testing → + to add a group (for example, Zach)."
step "Add yourself as a tester, and turn on automatic distribution, so every new build goes to the group."
step "On the Duo: install TestFlight from the App Store, signed in with the same Apple account, and accept the invite."
note "If App Store Connect won't make a group before the first build exists, do this after the first upload."
pause

finish
say "Next: run the TestFlight workflow (gh workflow run testflight.yml) and install the build from TestFlight on the Duo."
